-- Camply fresh install script
-- Generated by concatenating migration files 00..22 in order
-- (includes phase 2 : univers multi-tenant, partage par campagne,
-- et les correctifs 20/21/22 — récursion RLS campaigns, discriminateur
-- Discord dans username, backfill des profils manquants).
-- Use this file for a brand-new Supabase project.


-- ==================================================
-- BEGIN sql/00_schema.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Schéma Supabase
-- À coller dans : Supabase Dashboard > SQL Editor > New query
-- ══════════════════════════════════════════════════════════════


-- ── 1. Table profiles ─────────────────────────────────────────
-- Créée automatiquement à chaque inscription via un trigger.
-- Liée à auth.users (UUID Supabase Auth).

CREATE TABLE IF NOT EXISTS public.profiles (
  id         UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  username   TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Nombre d'univers qu'un utilisateur a le droit de posséder (owner_id).
-- Valeur ajustable manuellement en base par utilisateur si besoin.
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS max_universes INT NOT NULL DEFAULT 1;

-- Trigger : crée automatiquement un profil à l'inscription
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  INSERT INTO public.profiles (id, username)
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data->>'username', split_part(NEW.email, '@', 1))
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();




-- ── 2. Table characters ───────────────────────────────────────
-- Chaque personnage appartient à un utilisateur (user_id).
-- Les données du personnage sont stockées en JSONB (data).
-- is_public = true permet le partage via lien.

CREATE TABLE IF NOT EXISTS public.characters (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  name       TEXT NOT NULL DEFAULT '',
  rank       SMALLINT NOT NULL DEFAULT 5,
  is_public  BOOLEAN NOT NULL DEFAULT FALSE,
  data       JSONB NOT NULL DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Index pour retrouver rapidement les personnages d'un utilisateur
CREATE INDEX IF NOT EXISTS characters_user_id_idx ON public.characters(user_id);
-- Index pour les personnages publics
CREATE INDEX IF NOT EXISTS characters_public_idx ON public.characters(is_public) WHERE is_public = TRUE;

-- Trigger : met à jour updated_at automatiquement
CREATE OR REPLACE FUNCTION public.handle_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_characters_updated ON public.characters;
CREATE TRIGGER on_characters_updated
  BEFORE UPDATE ON public.characters
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();


-- ── 3. Row Level Security (RLS) ───────────────────────────────
-- RLS activé sur les deux tables.

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.characters ENABLE ROW LEVEL SECURITY;

-- profiles : chaque utilisateur lit et modifie uniquement son profil
DROP POLICY IF EXISTS "profiles_select_own" ON public.profiles;
CREATE POLICY "profiles_select_own"
  ON public.profiles FOR SELECT
  USING (auth.uid() = id);

DROP POLICY IF EXISTS "profiles_update_own" ON public.profiles;
CREATE POLICY "profiles_update_own"
  ON public.profiles FOR UPDATE
  USING (auth.uid() = id);

-- characters : lecture
--   → ses propres personnages (privés ou publics)
--   → les personnages publics d'autrui
DROP POLICY IF EXISTS "characters_select" ON public.characters;
CREATE POLICY "characters_select"
  ON public.characters FOR SELECT
  USING (
    auth.uid() = user_id       -- propriétaire
    OR is_public = TRUE        -- ou partagé publiquement
  );

-- characters : insertion uniquement pour soi-même
DROP POLICY IF EXISTS "characters_insert" ON public.characters;
CREATE POLICY "characters_insert"
  ON public.characters FOR INSERT
  WITH CHECK (auth.uid() = user_id);

-- ── 2. Table followed_characters ─────────────────────────────

CREATE TABLE IF NOT EXISTS public.followed_characters (
  user_id      UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  character_id UUID NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,
  followed_at  TIMESTAMPTZ DEFAULT NOW(),
  PRIMARY KEY (user_id, character_id)
);

CREATE INDEX IF NOT EXISTS followed_user_idx
  ON public.followed_characters(user_id);

-- characters : modification
--   → propriétaire
--   → ou utilisateur abonné au personnage via followed_characters
--     (utilisé pour permettre l'édition depuis le système de partage)
DROP POLICY IF EXISTS "characters_update" ON public.characters;
CREATE POLICY "characters_update"
  ON public.characters FOR UPDATE
  USING (
    auth.uid() = user_id
    OR EXISTS (
      SELECT 1
      FROM public.followed_characters fc
      WHERE fc.character_id = characters.id
        AND fc.user_id = auth.uid()
    )
  );

-- characters : suppression uniquement de ses propres personnages
DROP POLICY IF EXISTS "characters_delete" ON public.characters;
CREATE POLICY "characters_delete"
  ON public.characters FOR DELETE
  USING (auth.uid() = user_id);


-- ── 4. Accès public en lecture seule aux personnages publics ──
-- Permet aux utilisateurs non connectés de voir un personnage
-- partagé via lien (is_public = true), sans compte requis.

DROP POLICY IF EXISTS "characters_select_public_anon" ON public.characters;
CREATE POLICY "characters_select_public_anon"
  ON public.characters FOR SELECT
  TO anon
  USING (is_public = TRUE);


-- ══════════════════════════════════════════════════════════════
-- C'est tout ! Les tables sont prêtes.
-- Retournez dans l'application pour tester l'inscription.
-- ══════════════════════════════════════════════════════════════

-- END sql/00_schema.sql

-- ==================================================
-- BEGIN sql/01_tags.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Système de tags
-- À coller dans : Supabase Dashboard > SQL Editor > New query
-- ══════════════════════════════════════════════════════════════

-- ── 1. Table tags ─────────────────────────────────────────────
-- Un tag appartient à un utilisateur et a un nom unique par user.

CREATE TABLE IF NOT EXISTS public.tags (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  name       TEXT NOT NULL,
  color      TEXT NOT NULL DEFAULT '#5c6070',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (user_id, name)   -- un utilisateur ne peut pas avoir deux tags du même nom
);

CREATE INDEX IF NOT EXISTS tags_user_id_idx ON public.tags(user_id);


-- ── 2. Table character_tags (liaison) ─────────────────────────

CREATE TABLE IF NOT EXISTS public.character_tags (
  character_id UUID NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,
  tag_id       UUID NOT NULL REFERENCES public.tags(id) ON DELETE CASCADE,
  PRIMARY KEY (character_id, tag_id)
);

CREATE INDEX IF NOT EXISTS character_tags_character_idx ON public.character_tags(character_id);
CREATE INDEX IF NOT EXISTS character_tags_tag_idx ON public.character_tags(tag_id);


-- ── 3. RLS ────────────────────────────────────────────────────

ALTER TABLE public.tags ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.character_tags ENABLE ROW LEVEL SECURITY;

-- Tags : lecture, création, modification, suppression = propriétaire uniquement
DROP POLICY IF EXISTS "tags_select_own" ON public.tags;
CREATE POLICY "tags_select_own" ON public.tags FOR SELECT USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "tags_insert_own" ON public.tags;
CREATE POLICY "tags_insert_own" ON public.tags FOR INSERT WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "tags_update_own" ON public.tags;
CREATE POLICY "tags_update_own" ON public.tags FOR UPDATE USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "tags_delete_own" ON public.tags;
CREATE POLICY "tags_delete_own" ON public.tags FOR DELETE USING (auth.uid() = user_id);

-- character_tags : accessible si le personnage appartient à l'utilisateur
DROP POLICY IF EXISTS "character_tags_select" ON public.character_tags;
CREATE POLICY "character_tags_select" ON public.character_tags FOR SELECT
  USING (EXISTS (
    SELECT 1 FROM public.characters c
    WHERE c.id = character_id AND c.user_id = auth.uid()
  ));

DROP POLICY IF EXISTS "character_tags_insert" ON public.character_tags;
CREATE POLICY "character_tags_insert" ON public.character_tags FOR INSERT
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.characters c
    WHERE c.id = character_id AND c.user_id = auth.uid()
  ));

DROP POLICY IF EXISTS "character_tags_delete" ON public.character_tags;
CREATE POLICY "character_tags_delete" ON public.character_tags FOR DELETE
  USING (EXISTS (
    SELECT 1 FROM public.characters c
    WHERE c.id = character_id AND c.user_id = auth.uid()
  ));

-- ══════════════════════════════════════════════════════════════

-- END sql/01_tags.sql

-- ==================================================
-- BEGIN sql/02_followed.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Partage de personnages entre membres
-- À coller dans : Supabase Dashboard > SQL Editor > New query
-- ══════════════════════════════════════════════════════════════

-- ── 1. Colonne share_code sur characters ──────────────────────

ALTER TABLE public.characters
  ADD COLUMN IF NOT EXISTS share_code TEXT UNIQUE;

UPDATE public.characters
  SET share_code = upper(substr(md5(random()::text), 1, 8))
  WHERE share_code IS NULL;

CREATE OR REPLACE FUNCTION public.generate_share_code()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
  new_code TEXT;
  done BOOL := FALSE;
BEGIN
  WHILE NOT done LOOP
    new_code := upper(substr(md5(random()::text), 1, 8));
    done := TRUE;
    BEGIN
      NEW.share_code := new_code;
    EXCEPTION WHEN unique_violation THEN
      done := FALSE;
    END;
  END LOOP;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS set_share_code ON public.characters;
CREATE TRIGGER set_share_code
  BEFORE INSERT ON public.characters
  FOR EACH ROW
  WHEN (NEW.share_code IS NULL)
  EXECUTE FUNCTION public.generate_share_code();



-- ── 3. RLS ────────────────────────────────────────────────────

ALTER TABLE public.followed_characters ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "followed_select_own" ON public.followed_characters;
CREATE POLICY "followed_select_own"
  ON public.followed_characters FOR SELECT
  USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "followed_insert_own" ON public.followed_characters;
CREATE POLICY "followed_insert_own"
  ON public.followed_characters FOR INSERT
  WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "followed_delete_own" ON public.followed_characters;
CREATE POLICY "followed_delete_own"
  ON public.followed_characters FOR DELETE
  USING (auth.uid() = user_id);

-- END sql/02_followed.sql

