-- ==================================================
-- BEGIN sql/19_campaign_sharing.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Phase 2 : partage par campagne (membres)
-- À exécuter sur une base ayant déjà reçu sql/00_fresh_install.sql
-- puis sql/18_universes_phase1.sql.
--
-- Change de modèle :
--   • Un objet public (personnage/chronique/document/couche de
--     carte) n'est plus partagé via un share_code à transmettre :
--     il devient visible par tout utilisateur qui partage au
--     moins une campagne avec son propriétaire, dans le même
--     univers.
--   • Une campagne n'est plus une collection d'objets mais une
--     collection d'utilisateurs (campaign_members). Seul le
--     propriétaire de l'univers peut créer/gérer des campagnes ;
--     il y est automatiquement inscrit.
--   • Les codes de partage (share_code) et tout le bookkeeping
--     "follow" (followed_characters, followed_chronicles,
--     followed_documents, followed_map_layers, followed_campaigns,
--     campaign_items) disparaissent : la visibilité est calculée
--     par RLS, pas déclarée manuellement.
--
-- C'est une migration destructive (peu de données réelles à
-- préserver à ce stade) : les colonnes/tables obsolètes sont
-- supprimées sans tentative de backfill.
-- ══════════════════════════════════════════════════════════════


-- ══════════════════════════════════════════════════════════════
-- 1. Suppression de l'ancienne infrastructure de partage
-- ══════════════════════════════════════════════════════════════

DROP TABLE IF EXISTS public.followed_characters CASCADE;
DROP TABLE IF EXISTS public.followed_chronicles CASCADE;
DROP TABLE IF EXISTS public.followed_documents  CASCADE;
DROP TABLE IF EXISTS public.followed_map_layers CASCADE;
DROP TABLE IF EXISTS public.followed_campaigns  CASCADE;
DROP TABLE IF EXISTS public.campaign_items      CASCADE;

-- followed_character_tags / followed_document_tags / sync_owner_tags
-- sont conservées telles quelles : elles permettent à un utilisateur
-- de taguer un objet qu'il peut voir, indépendamment de tout
-- mécanisme de "follow". Seuls les appels frontend déclenchés par
-- l'ancien flux "suivre par code" disparaissent (côté JS).


-- ══════════════════════════════════════════════════════════════
-- 2. Suppression des share_code (colonnes, triggers, fonctions, index)
-- ══════════════════════════════════════════════════════════════

DROP TRIGGER IF EXISTS set_share_code              ON public.characters;
DROP TRIGGER IF EXISTS set_chronicle_share_code     ON public.chronicles;
DROP TRIGGER IF EXISTS set_document_share_code      ON public.documents;
DROP TRIGGER IF EXISTS set_map_layer_share_code     ON public.map_layers;
DROP TRIGGER IF EXISTS campaigns_share_code_trigger ON public.campaigns;

DROP FUNCTION IF EXISTS public.generate_share_code() CASCADE;
DROP FUNCTION IF EXISTS public.generate_campaign_share_code() CASCADE;
DROP FUNCTION IF EXISTS generate_campaign_share_code() CASCADE;

-- public.generate_short_code() est conservée : utilisée par
-- set_universe_join_code() pour universes.join_code (fonctionnalité
-- non concernée par ce changement).

DROP INDEX IF EXISTS public.characters_universe_share_code_idx;
DROP INDEX IF EXISTS public.chronicles_universe_share_code_idx;
DROP INDEX IF EXISTS public.documents_universe_share_code_idx;
DROP INDEX IF EXISTS public.campaigns_universe_share_code_idx;
DROP INDEX IF EXISTS public.map_layers_universe_share_code_idx;
DROP INDEX IF EXISTS public.map_markers_share_code_idx;
DROP INDEX IF EXISTS public.campaigns_share_code_idx;

ALTER TABLE public.characters  DROP COLUMN IF EXISTS share_code;
ALTER TABLE public.chronicles  DROP COLUMN IF EXISTS share_code;
ALTER TABLE public.documents   DROP COLUMN IF EXISTS share_code;
ALTER TABLE public.map_layers  DROP COLUMN IF EXISTS share_code;
ALTER TABLE public.map_markers DROP COLUMN IF EXISTS share_code;
ALTER TABLE public.campaigns   DROP COLUMN IF EXISTS share_code;
ALTER TABLE public.campaigns   DROP COLUMN IF EXISTS is_public CASCADE;

-- guard_document_shared_update référençait share_code : on la
-- redéfinit sans cette colonne (allow_write_share reste protégée
-- pour un non-propriétaire).
CREATE OR REPLACE FUNCTION public.guard_document_shared_update()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  IF auth.uid() IS DISTINCT FROM OLD.user_id THEN
    NEW.user_id := OLD.user_id;
    NEW.is_public := OLD.is_public;
    NEW.allow_write_share := OLD.allow_write_share;
  END IF;
  RETURN NEW;
END;
$$;


-- ══════════════════════════════════════════════════════════════
-- 3. Campagnes = collections d'utilisateurs
-- ══════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS public.campaign_members (
  campaign_id UUID NOT NULL REFERENCES public.campaigns(id) ON DELETE CASCADE,
  user_id     UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  added_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (campaign_id, user_id)
);

CREATE INDEX IF NOT EXISTS campaign_members_user_idx ON public.campaign_members(user_id);

-- Le propriétaire de l'univers est automatiquement membre de
-- chaque campagne qu'il crée.
CREATE OR REPLACE FUNCTION public.add_universe_owner_to_campaign()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_owner_id UUID;
BEGIN
  SELECT owner_id INTO v_owner_id FROM public.universes WHERE id = NEW.universe_id;
  IF v_owner_id IS NOT NULL THEN
    INSERT INTO public.campaign_members (campaign_id, user_id)
    VALUES (NEW.id, v_owner_id)
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_campaign_created_add_owner ON public.campaigns;
CREATE TRIGGER on_campaign_created_add_owner
  AFTER INSERT ON public.campaigns
  FOR EACH ROW EXECUTE FUNCTION public.add_universe_owner_to_campaign();


-- ══════════════════════════════════════════════════════════════
-- 4. Helper : deux utilisateurs partagent-ils une campagne ?
-- ══════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.shares_campaign_with(
  p_universe_id UUID,
  p_owner_id    UUID,
  p_viewer_id   UUID DEFAULT auth.uid()
)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
  -- Tant qu'aucune campagne n'existe dans l'univers, celui-ci se comporte
  -- comme une seule campagne implicite regroupant tous ses membres : le
  -- contenu public reste visible à tous plutôt que d'être isolé en silo.
  SELECT CASE
    WHEN NOT EXISTS (SELECT 1 FROM public.campaigns c WHERE c.universe_id = p_universe_id)
      THEN public.is_universe_member(p_universe_id, p_owner_id)
       AND public.is_universe_member(p_universe_id, p_viewer_id)
    ELSE EXISTS (
      SELECT 1
      FROM public.campaign_members cm1
      JOIN public.campaign_members cm2 ON cm2.campaign_id = cm1.campaign_id
      JOIN public.campaigns c ON c.id = cm1.campaign_id
      WHERE c.universe_id = p_universe_id
        AND cm1.user_id = p_owner_id
        AND cm2.user_id = p_viewer_id
    )
  END;
$$;

GRANT EXECUTE ON FUNCTION public.shares_campaign_with(UUID, UUID, UUID) TO authenticated;

-- Un membre 'gm' (ou le propriétaire) peut écrire sur les objets publics
-- partagés avec lui via une campagne commune (personnages, chroniques,
-- entrées, documents, couches de carte). Les simples joueurs restent en
-- lecture seule sur ces mêmes objets.
CREATE OR REPLACE FUNCTION public.can_gm_edit(
  p_universe_id UUID,
  p_owner_id    UUID,
  p_editor_id   UUID DEFAULT auth.uid()
)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
  SELECT public.has_universe_role(p_universe_id, ARRAY['owner', 'gm'], p_editor_id)
     AND public.shares_campaign_with(p_universe_id, p_owner_id, p_editor_id);
$$;

GRANT EXECUTE ON FUNCTION public.can_gm_edit(UUID, UUID, UUID) TO authenticated;


-- ══════════════════════════════════════════════════════════════
-- 4bis. Sélection d'objets MJ visibles par campagne
-- ══════════════════════════════════════════════════════════════
-- Le contenu créé par le MJ (owner/gm de l'univers) peut être restreint
-- à des campagnes précises : le MJ coche, pour chaque campagne, quels
-- objets publics doivent être visibles par ses membres. Cette table de
-- jonction ne s'applique qu'au contenu "côté MJ" — les personnages
-- publics des simples joueurs restent visibles à toute leur campagne
-- sans sélection explicite (cf. shares_campaign_with).

CREATE OR REPLACE FUNCTION public.gm_owns_and_restricted(
  p_universe_id UUID,
  p_owner_id    UUID
)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
  SELECT public.has_universe_role(p_universe_id, ARRAY['owner', 'gm'], p_owner_id)
     AND EXISTS (SELECT 1 FROM public.campaigns c WHERE c.universe_id = p_universe_id);
$$;

GRANT EXECUTE ON FUNCTION public.gm_owns_and_restricted(UUID, UUID) TO authenticated;

CREATE TABLE IF NOT EXISTS public.campaign_visible_characters (
  campaign_id  UUID NOT NULL REFERENCES public.campaigns(id)  ON DELETE CASCADE,
  character_id UUID NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,
  added_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (campaign_id, character_id)
);

CREATE TABLE IF NOT EXISTS public.campaign_visible_chronicles (
  campaign_id  UUID NOT NULL REFERENCES public.campaigns(id)  ON DELETE CASCADE,
  chronicle_id UUID NOT NULL REFERENCES public.chronicles(id) ON DELETE CASCADE,
  added_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (campaign_id, chronicle_id)
);

CREATE TABLE IF NOT EXISTS public.campaign_visible_documents (
  campaign_id UUID NOT NULL REFERENCES public.campaigns(id) ON DELETE CASCADE,
  document_id UUID NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE,
  added_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (campaign_id, document_id)
);

CREATE TABLE IF NOT EXISTS public.campaign_visible_maps (
  campaign_id  UUID NOT NULL REFERENCES public.campaigns(id)  ON DELETE CASCADE,
  map_layer_id UUID NOT NULL REFERENCES public.map_layers(id) ON DELETE CASCADE,
  added_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (campaign_id, map_layer_id)
);

CREATE INDEX IF NOT EXISTS campaign_visible_characters_char_idx ON public.campaign_visible_characters(character_id);
CREATE INDEX IF NOT EXISTS campaign_visible_chronicles_chr_idx  ON public.campaign_visible_chronicles(chronicle_id);
CREATE INDEX IF NOT EXISTS campaign_visible_documents_doc_idx   ON public.campaign_visible_documents(document_id);
CREATE INDEX IF NOT EXISTS campaign_visible_maps_map_idx        ON public.campaign_visible_maps(map_layer_id);

ALTER TABLE public.campaign_visible_characters ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.campaign_visible_chronicles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.campaign_visible_documents  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.campaign_visible_maps       ENABLE ROW LEVEL SECURITY;

-- Gérées exclusivement par le propriétaire de l'univers (même pattern
-- que campaign_members_*), mais lisibles aussi par les membres de la
-- campagne concernée puisque les policies de contenu en dépendent.
DROP POLICY IF EXISTS "campaign_visible_characters_select" ON public.campaign_visible_characters;
CREATE POLICY "campaign_visible_characters_select" ON public.campaign_visible_characters FOR SELECT
  USING (
    EXISTS (SELECT 1 FROM public.campaign_members cm WHERE cm.campaign_id = campaign_id AND cm.user_id = auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.campaigns c
      WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
    )
  );

DROP POLICY IF EXISTS "campaign_visible_characters_write" ON public.campaign_visible_characters;
CREATE POLICY "campaign_visible_characters_write" ON public.campaign_visible_characters FOR ALL
  USING (EXISTS (
    SELECT 1 FROM public.campaigns c
    WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
  ))
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.campaigns c
    WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
  ));

DROP POLICY IF EXISTS "campaign_visible_chronicles_select" ON public.campaign_visible_chronicles;
CREATE POLICY "campaign_visible_chronicles_select" ON public.campaign_visible_chronicles FOR SELECT
  USING (
    EXISTS (SELECT 1 FROM public.campaign_members cm WHERE cm.campaign_id = campaign_id AND cm.user_id = auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.campaigns c
      WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
    )
  );

DROP POLICY IF EXISTS "campaign_visible_chronicles_write" ON public.campaign_visible_chronicles;
CREATE POLICY "campaign_visible_chronicles_write" ON public.campaign_visible_chronicles FOR ALL
  USING (EXISTS (
    SELECT 1 FROM public.campaigns c
    WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
  ))
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.campaigns c
    WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
  ));

DROP POLICY IF EXISTS "campaign_visible_documents_select" ON public.campaign_visible_documents;
CREATE POLICY "campaign_visible_documents_select" ON public.campaign_visible_documents FOR SELECT
  USING (
    EXISTS (SELECT 1 FROM public.campaign_members cm WHERE cm.campaign_id = campaign_id AND cm.user_id = auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.campaigns c
      WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
    )
  );

DROP POLICY IF EXISTS "campaign_visible_documents_write" ON public.campaign_visible_documents;
CREATE POLICY "campaign_visible_documents_write" ON public.campaign_visible_documents FOR ALL
  USING (EXISTS (
    SELECT 1 FROM public.campaigns c
    WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
  ))
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.campaigns c
    WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
  ));

DROP POLICY IF EXISTS "campaign_visible_maps_select" ON public.campaign_visible_maps;
CREATE POLICY "campaign_visible_maps_select" ON public.campaign_visible_maps FOR SELECT
  USING (
    EXISTS (SELECT 1 FROM public.campaign_members cm WHERE cm.campaign_id = campaign_id AND cm.user_id = auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.campaigns c
      WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
    )
  );

DROP POLICY IF EXISTS "campaign_visible_maps_write" ON public.campaign_visible_maps;
CREATE POLICY "campaign_visible_maps_write" ON public.campaign_visible_maps FOR ALL
  USING (EXISTS (
    SELECT 1 FROM public.campaigns c
    WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
  ))
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.campaigns c
    WHERE c.id = campaign_id AND public.has_universe_role(c.universe_id, ARRAY['owner'])
