-- ══════════════════════════════════════════════════════════════
-- 5. RLS — campaigns / campaign_members
-- ══════════════════════════════════════════════════════════════

DROP POLICY IF EXISTS campaigns_owner  ON public.campaigns;
DROP POLICY IF EXISTS campaigns_public ON public.campaigns;

CREATE POLICY "campaigns_select" ON public.campaigns FOR SELECT
  USING (
    public.has_universe_role(universe_id, ARRAY['owner'])
    OR EXISTS (
      SELECT 1 FROM public.campaign_members cm
      WHERE cm.campaign_id = id AND cm.user_id = auth.uid()
    )
  );

CREATE POLICY "campaigns_insert_owner" ON public.campaigns FOR INSERT
  WITH CHECK (
    user_id = auth.uid()
    AND public.has_universe_role(universe_id, ARRAY['owner'])
  );

CREATE POLICY "campaigns_update_owner" ON public.campaigns FOR UPDATE
  USING (public.has_universe_role(universe_id, ARRAY['owner']))
  WITH CHECK (public.has_universe_role(universe_id, ARRAY['owner']));

CREATE POLICY "campaigns_delete_owner" ON public.campaigns FOR DELETE
  USING (public.has_universe_role(universe_id, ARRAY['owner']));

ALTER TABLE public.campaign_members ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS campaign_items_owner  ON public.campaign_members;
DROP POLICY IF EXISTS campaign_items_public ON public.campaign_members;

CREATE POLICY "campaign_members_select" ON public.campaign_members FOR SELECT
  USING (
    user_id = auth.uid()
    OR EXISTS (
      SELECT 1 FROM public.campaigns c
      WHERE c.id = campaign_id
        AND public.has_universe_role(c.universe_id, ARRAY['owner'])
    )
  );

CREATE POLICY "campaign_members_insert_owner" ON public.campaign_members FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.campaigns c
      WHERE c.id = campaign_id
        AND public.has_universe_role(c.universe_id, ARRAY['owner'])
    )
  );

CREATE POLICY "campaign_members_delete_owner" ON public.campaign_members FOR DELETE
  USING (
    EXISTS (
      SELECT 1 FROM public.campaigns c
      WHERE c.id = campaign_id
        AND public.has_universe_role(c.universe_id, ARRAY['owner'])
    )
  );


-- ══════════════════════════════════════════════════════════════
-- 6. RLS — tables de contenu (visibilité scoped par campagne)
-- ══════════════════════════════════════════════════════════════

-- Personnages : lecture propriétaire OU public+campagne commune. Si le
-- propriétaire est MJ/owner et qu'au moins une campagne existe, l'objet
-- doit en plus avoir été coché comme visible pour l'une des campagnes
-- communes (cf. campaign_visible_characters).
DROP POLICY IF EXISTS "characters_select" ON public.characters;
CREATE POLICY "characters_select" ON public.characters FOR SELECT
  USING (
    auth.uid() = user_id
    OR (
      is_public = TRUE
      AND public.shares_campaign_with(universe_id, user_id, auth.uid())
      AND (
        NOT public.gm_owns_and_restricted(universe_id, user_id)
        OR EXISTS (
          SELECT 1
          FROM public.campaign_members cm
          JOIN public.campaigns c ON c.id = cm.campaign_id
          JOIN public.campaign_visible_characters cvc ON cvc.campaign_id = c.id
          WHERE c.universe_id = characters.universe_id
            AND cm.user_id = auth.uid()
            AND cvc.character_id = characters.id
        )
      )
    )
  );

-- Édition : propriétaire, OU membre 'gm'/'owner' de l'univers partageant
-- une campagne avec le propriétaire de l'objet (droits d'édition MJ).
-- Un simple joueur ne peut voir un objet partagé public que pour le
-- consulter, pas pour l'éditer.
DROP POLICY IF EXISTS "characters_update" ON public.characters;
CREATE POLICY "characters_update" ON public.characters FOR UPDATE
  USING (
    auth.uid() = user_id
    OR (is_public = TRUE AND public.can_gm_edit(universe_id, user_id, auth.uid()))
  );

-- Chroniques
DROP POLICY IF EXISTS "chronicles_select" ON public.chronicles;
CREATE POLICY "chronicles_select" ON public.chronicles FOR SELECT
  USING (
    auth.uid() = user_id
    OR (
      is_public = TRUE
      AND public.shares_campaign_with(universe_id, user_id, auth.uid())
      AND (
        NOT public.gm_owns_and_restricted(universe_id, user_id)
        OR EXISTS (
          SELECT 1
          FROM public.campaign_members cm
          JOIN public.campaigns c ON c.id = cm.campaign_id
          JOIN public.campaign_visible_chronicles cvc ON cvc.campaign_id = c.id
          WHERE c.universe_id = chronicles.universe_id
            AND cm.user_id = auth.uid()
            AND cvc.chronicle_id = chronicles.id
        )
      )
    )
  );

DROP POLICY IF EXISTS "chronicles_update" ON public.chronicles;
CREATE POLICY "chronicles_update" ON public.chronicles FOR UPDATE
  USING (
    auth.uid() = user_id
    OR (is_public = TRUE AND public.can_gm_edit(universe_id, user_id, auth.uid()))
  );

DROP POLICY IF EXISTS "entries_select" ON public.chronicle_entries;
CREATE POLICY "entries_select" ON public.chronicle_entries FOR SELECT
  USING (EXISTS (
    SELECT 1 FROM public.chronicles c
    WHERE c.id = chronicle_id
      AND (
        c.user_id = auth.uid()
        OR (
          c.is_public = TRUE
          AND public.shares_campaign_with(c.universe_id, c.user_id, auth.uid())
          AND (
            NOT public.gm_owns_and_restricted(c.universe_id, c.user_id)
            OR EXISTS (
              SELECT 1
              FROM public.campaign_members cm
              JOIN public.campaigns cc ON cc.id = cm.campaign_id
              JOIN public.campaign_visible_chronicles cvc ON cvc.campaign_id = cc.id
              WHERE cc.universe_id = c.universe_id
                AND cm.user_id = auth.uid()
                AND cvc.chronicle_id = c.id
            )
          )
        )
      )
  ));

-- Un MJ peut créer/modifier des entrées dans une chronique publique
-- partagée avec lui, au même titre que son propriétaire.
DROP POLICY IF EXISTS "entries_insert" ON public.chronicle_entries;
CREATE POLICY "entries_insert" ON public.chronicle_entries FOR INSERT
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.chronicles c
    WHERE c.id = chronicle_id
      AND (
        c.user_id = auth.uid()
        OR (c.is_public = TRUE AND public.can_gm_edit(c.universe_id, c.user_id, auth.uid()))
      )
  ));

DROP POLICY IF EXISTS "entries_update" ON public.chronicle_entries;
CREATE POLICY "entries_update" ON public.chronicle_entries FOR UPDATE
  USING (EXISTS (
    SELECT 1 FROM public.chronicles c
    WHERE c.id = chronicle_id
      AND (
        c.user_id = auth.uid()
        OR (c.is_public = TRUE AND public.can_gm_edit(c.universe_id, c.user_id, auth.uid()))
      )
  ));

-- Documents
DROP POLICY IF EXISTS "documents_select" ON public.documents;
CREATE POLICY "documents_select" ON public.documents FOR SELECT
  USING (
    auth.uid() = user_id
    OR (
      is_public = TRUE
      AND public.shares_campaign_with(universe_id, user_id, auth.uid())
      AND (
        NOT public.gm_owns_and_restricted(universe_id, user_id)
        OR EXISTS (
          SELECT 1
          FROM public.campaign_members cm
          JOIN public.campaigns c ON c.id = cm.campaign_id
          JOIN public.campaign_visible_documents cvd ON cvd.campaign_id = c.id
          WHERE c.universe_id = documents.universe_id
            AND cm.user_id = auth.uid()
            AND cvd.document_id = documents.id
        )
      )
    )
  );

-- Un MJ a toujours le droit d'écriture sur un document public partagé,
-- même si son propriétaire n'a pas activé allow_write_share (ce flag ne
-- régit que la co-édition entre simples joueurs). Le volet co-édition
-- (allow_write_share) reprend la même restriction de visibilité que la
-- lecture : un joueur ne peut pas écrire sur un document MJ qu'il ne
-- peut pas voir.
DROP POLICY IF EXISTS "documents_update" ON public.documents;
CREATE POLICY "documents_update" ON public.documents FOR UPDATE
  USING (
    auth.uid() = user_id
    OR (
      allow_write_share = TRUE
      AND is_public = TRUE
      AND public.shares_campaign_with(universe_id, user_id, auth.uid())
      AND (
        NOT public.gm_owns_and_restricted(universe_id, user_id)
        OR EXISTS (
          SELECT 1
          FROM public.campaign_members cm
          JOIN public.campaigns c ON c.id = cm.campaign_id
          JOIN public.campaign_visible_documents cvd ON cvd.campaign_id = c.id
          WHERE c.universe_id = documents.universe_id
            AND cm.user_id = auth.uid()
            AND cvd.document_id = documents.id
        )
      )
    )
    OR (is_public = TRUE AND public.can_gm_edit(universe_id, user_id, auth.uid()))
  )
  WITH CHECK (
    auth.uid() = user_id
    OR (
      allow_write_share = TRUE
      AND is_public = TRUE
      AND public.shares_campaign_with(universe_id, user_id, auth.uid())
      AND (
        NOT public.gm_owns_and_restricted(universe_id, user_id)
        OR EXISTS (
          SELECT 1
          FROM public.campaign_members cm
          JOIN public.campaigns c ON c.id = cm.campaign_id
          JOIN public.campaign_visible_documents cvd ON cvd.campaign_id = c.id
          WHERE c.universe_id = documents.universe_id
            AND cm.user_id = auth.uid()
            AND cvd.document_id = documents.id
        )
      )
    )
    OR (is_public = TRUE AND public.can_gm_edit(universe_id, user_id, auth.uid()))
  );

-- Couches de carte
DROP POLICY IF EXISTS "map_layers_select" ON public.map_layers;
CREATE POLICY "map_layers_select" ON public.map_layers FOR SELECT
  USING (
    auth.uid() = user_id
    OR (
      is_public = TRUE
      AND public.shares_campaign_with(universe_id, user_id, auth.uid())
      AND (
        NOT public.gm_owns_and_restricted(universe_id, user_id)
        OR EXISTS (
          SELECT 1
          FROM public.campaign_members cm
          JOIN public.campaigns c ON c.id = cm.campaign_id
          JOIN public.campaign_visible_maps cvm ON cvm.campaign_id = c.id
          WHERE c.universe_id = map_layers.universe_id
            AND cm.user_id = auth.uid()
            AND cvm.map_layer_id = map_layers.id
        )
      )
    )
  );

-- Un MJ peut modifier une couche de carte publique partagée avec lui
-- (mais pas en créer une nouvelle au nom d'un autre joueur : une seule
-- couche par utilisateur, cf. contrainte UNIQUE(user_id)).
DROP POLICY IF EXISTS "map_layers_update" ON public.map_layers;
CREATE POLICY "map_layers_update" ON public.map_layers FOR UPDATE
  USING (
    auth.uid() = user_id
    OR (is_public = TRUE AND public.can_gm_edit(universe_id, user_id, auth.uid()))
  );

-- Marqueurs de carte : visibles si la couche correspondante
-- (même user_id + map_key) est publique et partagée via campagne.
DROP POLICY IF EXISTS "map_markers_select_followed" ON public.map_markers;
CREATE POLICY "map_markers_select_shared" ON public.map_markers FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.map_layers ml
      WHERE ml.user_id  = map_markers.user_id
        AND ml.map_key  = map_markers.map_key
        AND ml.is_public = TRUE
        AND public.shares_campaign_with(ml.universe_id, ml.user_id, auth.uid())
        AND (
          NOT public.gm_owns_and_restricted(ml.universe_id, ml.user_id)
          OR EXISTS (
            SELECT 1
            FROM public.campaign_members cm
            JOIN public.campaigns c ON c.id = cm.campaign_id
            JOIN public.campaign_visible_maps cvm ON cvm.campaign_id = c.id
            WHERE c.universe_id = ml.universe_id
              AND cm.user_id = auth.uid()
              AND cvm.map_layer_id = ml.id
          )
        )
    )
  );

-- Un MJ peut créer/modifier/supprimer les marqueurs d'une couche
-- publique partagée avec lui, comme s'il en était le propriétaire.
DROP POLICY IF EXISTS "map_markers_all_own" ON public.map_markers;
CREATE POLICY "map_markers_all_own" ON public.map_markers FOR ALL
  USING (
    auth.uid() = user_id
    OR (
      EXISTS (
        SELECT 1 FROM public.map_layers ml
        WHERE ml.user_id = map_markers.user_id
          AND ml.map_key = map_markers.map_key
          AND ml.is_public = TRUE
      )
      AND public.can_gm_edit(map_markers.universe_id, map_markers.user_id, auth.uid())
    )
  )
  WITH CHECK (
    auth.uid() = user_id
    OR (
      EXISTS (
        SELECT 1 FROM public.map_layers ml
        WHERE ml.user_id = map_markers.user_id
          AND ml.map_key = map_markers.map_key
          AND ml.is_public = TRUE
      )
      AND public.can_gm_edit(map_markers.universe_id, map_markers.user_id, auth.uid())
    )
  );

-- Notes secrètes sur un personnage : on ne peut en écrire une que
-- sur un personnage qu'on peut voir (propriétaire ou public+campagne).
DROP POLICY IF EXISTS "character_secrets_own_notes" ON public.character_secrets;
CREATE POLICY "character_secrets_own_notes" ON public.character_secrets FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (
    user_id = auth.uid()
    AND EXISTS (
      SELECT 1 FROM public.characters c
      WHERE c.id = character_id
        AND (
          c.user_id = auth.uid()
          OR (c.is_public = TRUE AND public.shares_campaign_with(c.universe_id, c.user_id, auth.uid()))
        )
    )
  );

-- Note : les policies "*_select_anon" (lecture par lien public sans
-- compte, sur characters/chronicles/chronicle_entries/documents/
-- map_layers/map_markers) sont laissées inchangées — elles sont
-- orthogonales au partage inter-utilisateurs de l'univers. Elles
-- deviennent simplement inatteignables une fois l'UI de génération
-- de lien retirée côté frontend.


-- ══════════════════════════════════════════════════════════════
-- 7. transfer_item : recherche par id au lieu de share_code
-- ══════════════════════════════════════════════════════════════

DROP FUNCTION IF EXISTS public.transfer_item(TEXT, TEXT, TEXT);

CREATE OR REPLACE FUNCTION public.transfer_item(
  p_item_type   TEXT,   -- 'char' | 'chr' | 'doc' | 'map'
  p_item_id     UUID,
  p_to_username TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_caller_id    UUID := auth.uid();
  v_target_id    UUID;
  v_item_user_id UUID;
  v_map_key      TEXT;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated');
  END IF;

  SELECT id INTO v_target_id
  FROM public.profiles
  WHERE lower(username) = lower(trim(p_to_username))
  LIMIT 1;

  IF v_target_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'user_not_found');
  END IF;

  IF v_target_id = v_caller_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'same_user');
  END IF;

  IF p_item_type = 'char' THEN
    SELECT user_id INTO v_item_user_id FROM public.characters WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    PERFORM public._cleanup_char_tags_on_transfer(p_item_id, v_caller_id);
    UPDATE public.characters SET user_id = v_target_id, updated_at = NOW() WHERE id = p_item_id;

  ELSIF p_item_type = 'chr' THEN
    SELECT user_id INTO v_item_user_id FROM public.chronicles WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    UPDATE public.chronicles SET user_id = v_target_id, updated_at = NOW() WHERE id = p_item_id;

  ELSIF p_item_type = 'doc' THEN
    SELECT user_id INTO v_item_user_id FROM public.documents WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    PERFORM public._cleanup_doc_tags_on_transfer(p_item_id, v_caller_id);
    UPDATE public.documents SET user_id = v_target_id, updated_at = NOW() WHERE id = p_item_id;

  ELSIF p_item_type = 'map' THEN
    SELECT user_id, map_key INTO v_item_user_id, v_map_key FROM public.map_layers WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    -- Transfère uniquement les marqueurs de la carte concernée (comme avant).
    UPDATE public.map_markers
      SET user_id = v_target_id, updated_at = NOW()
      WHERE user_id = v_caller_id AND map_key = v_map_key;
    UPDATE public.map_layers
      SET user_id = v_target_id, updated_at = NOW()
      WHERE id = p_item_id;

  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_type');
  END IF;

  RETURN jsonb_build_object('ok', true, 'item_id', p_item_id, 'to_user_id', v_target_id);
END;
$$;

GRANT EXECUTE ON FUNCTION public.transfer_item(TEXT, UUID, TEXT) TO authenticated;

-- Note : le type 'campaign' n'est plus transférable — une campagne
-- appartient structurellement au propriétaire de l'univers, qui est
-- seul habilité à en créer et à en gérer les membres.

-- ══════════════════════════════════════════════════════════════
-- Fin — voir campaigns.js / scripts.js / chronicles.js / documents.js
-- / map.js / transfert.js / index.html pour la partie frontend
-- correspondante (requêtes rebasées sur universe_id + id, plus de
-- share_code ni de flux "suivre par code").
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/19_campaign_sharing.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/20_fix_campaigns_rls_recursion.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Correctif : récursion infinie RLS campaigns
-- À exécuter sur une base ayant déjà reçu sql/19_campaign_sharing.sql.
--
-- Bug : campaigns_select interroge campaign_members en EXISTS(...) et
-- campaign_members_select/insert/delete interrogent campaigns en
-- EXISTS(...). Les deux tables ayant RLS activé, évaluer la policy de
-- l'une déclenche l'évaluation de la policy de l'autre, qui rappelle
-- la première : Postgres lève 42P17 "infinite recursion detected in
-- policy for relation campaigns".
--
-- Correctif : router ces vérifications croisées par des fonctions
-- SECURITY DEFINER (même schéma que has_universe_role /
-- shares_campaign_with), qui contournent le RLS de la table
-- interrogée en leur sein et cassent donc le cycle.
-- ══════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.is_campaign_member(
  p_campaign_id UUID,
  p_user_id     UUID DEFAULT auth.uid()
)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.campaign_members cm
    WHERE cm.campaign_id = p_campaign_id AND cm.user_id = p_user_id
  );
$$;

GRANT EXECUTE ON FUNCTION public.is_campaign_member(UUID, UUID) TO authenticated;

CREATE OR REPLACE FUNCTION public.is_campaign_universe_owner(
  p_campaign_id UUID,
  p_user_id     UUID DEFAULT auth.uid()
)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.campaigns c
    WHERE c.id = p_campaign_id
      AND public.has_universe_role(c.universe_id, ARRAY['owner'], p_user_id)
  );
$$;

GRANT EXECUTE ON FUNCTION public.is_campaign_universe_owner(UUID, UUID) TO authenticated;

-- campaigns_select : remplace le EXISTS(campaign_members) brut
DROP POLICY IF EXISTS "campaigns_select" ON public.campaigns;
CREATE POLICY "campaigns_select" ON public.campaigns FOR SELECT
  USING (
    public.has_universe_role(universe_id, ARRAY['owner'])
    OR public.is_campaign_member(id)
  );

-- campaign_members_* : remplace le EXISTS(campaigns) brut
DROP POLICY IF EXISTS "campaign_members_select" ON public.campaign_members;
CREATE POLICY "campaign_members_select" ON public.campaign_members FOR SELECT
  USING (
    user_id = auth.uid()
    OR public.is_campaign_universe_owner(campaign_id)
  );

DROP POLICY IF EXISTS "campaign_members_insert_owner" ON public.campaign_members;
CREATE POLICY "campaign_members_insert_owner" ON public.campaign_members FOR INSERT
  WITH CHECK (public.is_campaign_universe_owner(campaign_id));

DROP POLICY IF EXISTS "campaign_members_delete_owner" ON public.campaign_members;
CREATE POLICY "campaign_members_delete_owner" ON public.campaign_members FOR DELETE
  USING (public.is_campaign_universe_owner(campaign_id));

-- ==================================================
-- END sql/20_fix_campaigns_rls_recursion.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/21_fix_username_discriminator.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Correctif : discriminateur Discord dans username
-- À exécuter sur une base ayant déjà reçu sql/00_fresh_install.sql.
--
-- Bug : raw_user_meta_data->>'full_name' renvoie parfois
-- "pseudo#0" (discriminateur legacy que Discord ajoute encore pour
-- les comptes migrés au nouveau système de pseudos). Ce suffixe se
-- retrouvait tel quel dans profiles.username, ce qui cassait la
-- recherche d'invitation (l'utilisateur tape "pseudo", la base
-- contient "pseudo#0" → aucune correspondance).
--
-- Ce correctif : (1) nettoie le trigger de création de profil pour
-- les futurs comptes, (2) corrige rétroactivement les profils déjà
-- en base.
-- ══════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_username TEXT;
BEGIN
  v_username := COALESCE(
    NEW.raw_user_meta_data->>'full_name',
    NEW.raw_user_meta_data->>'name',
    NEW.raw_user_meta_data->>'username',
    split_part(NEW.email, '@', 1)
  );
  v_username := regexp_replace(v_username, '#[0-9]+$', '');

  INSERT INTO public.profiles (id, username)
  VALUES (NEW.id, v_username)
  ON CONFLICT (id) DO UPDATE SET username = EXCLUDED.username;
  RETURN NEW;
END;
$$;

UPDATE public.profiles
SET username = regexp_replace(username, '#[0-9]+$', '')
WHERE username ~ '#[0-9]+$';

-- ==================================================
-- END sql/21_fix_username_discriminator.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/22_backfill_missing_profiles.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Correctif : profils manquants
-- À exécuter sur une base ayant déjà reçu sql/00_fresh_install.sql
-- et sql/21_fix_username_discriminator.sql.
--
-- Constat : public.profiles est vide alors que auth.users contient
-- des comptes existants (ex. connectés depuis avril). Le trigger
-- on_auth_user_created (AFTER INSERT ON auth.users) n'a jamais
-- créé leur ligne, et le code client ne faisait qu'un UPDATE à
-- chaque connexion (0 ligne affectée si elle n'existe pas, sans
-- erreur) — rien ne créait donc la ligne après coup.
--
-- Ce correctif :
--   1. Réaffirme le trigger de création (filet de sécurité pour
--      les futures inscriptions).
--   2. Backfill : crée la ligne profiles manquante pour chaque
--      compte auth.users existant.
-- (Le client fait désormais un upsert à chaque connexion, cf.
-- scripts.js — ce backfill couvre les comptes qui ne se sont pas
-- reconnectés depuis ce correctif.)
-- ══════════════════════════════════════════════════════════════

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

INSERT INTO public.profiles (id, username)
SELECT
  u.id,
  regexp_replace(
    COALESCE(
      u.raw_user_meta_data->>'full_name',
      u.raw_user_meta_data->>'name',
      u.raw_user_meta_data->>'username',
      split_part(u.email, '@', 1)
    ),
    '#[0-9]+$', ''
  )
FROM auth.users u
LEFT JOIN public.profiles p ON p.id = u.id
WHERE p.id IS NULL;

-- ==================================================
-- END sql/22_backfill_missing_profiles.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/23_maps_config.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Configuration des cartes via l'interface
--
-- Remplace map-config.js : chaque carte (image, nom, dimensions,
-- libellés des couleurs de marqueurs) devient une ligne de
-- public.maps, gérée depuis Configuration > Cartes (owner
-- de l'univers uniquement).
--
-- Le partage des marqueurs/couches (map_markers / map_layers,
-- cf. sql/16_map_sharing.sql plus haut dans ce fichier) référence
-- déjà map_key comme un simple texte sans clé étrangère : cette
-- migration ne touche à aucune policy existante sur ces tables,
-- elle fournit uniquement les métadonnées de rendu (image, nom,
-- libellés de couleurs) que le client associe par correspondance
-- de map_key.
-- ══════════════════════════════════════════════════════════════

-- ── 1. Table principale ──────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.maps (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  universe_id   UUID NOT NULL REFERENCES public.universes(id) ON DELETE CASCADE,
  created_by    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  map_key       TEXT NOT NULL,
  name          TEXT NOT NULL CHECK (length(trim(name)) > 0),
  image_url     TEXT NOT NULL DEFAULT '',
  image_width   INT  NOT NULL CHECK (image_width  > 0),
  image_height  INT  NOT NULL CHECK (image_height > 0),
  marker_colors JSONB NOT NULL DEFAULT '[]'::jsonb, -- [{color:'#e05c5c', label:'Rouge'}, ...]
  sort_order    INT  NOT NULL DEFAULT 0,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (universe_id, map_key)
);

CREATE INDEX IF NOT EXISTS maps_universe_idx ON public.maps(universe_id);

DROP TRIGGER IF EXISTS on_maps_updated ON public.maps;
CREATE TRIGGER on_maps_updated
  BEFORE UPDATE ON public.maps
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

-- ── 2. Génération automatique de map_key (slug) à la création ──
-- Le slug n'est jamais saisi par l'utilisateur : il est dérivé du
-- nom, avec gestion des collisions au sein d'un même univers
-- (même principe que set_universe_join_code plus haut).
CREATE OR REPLACE FUNCTION public.set_map_key()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  base_slug TEXT;
  candidate TEXT;
  attempt   INT := 1;
BEGIN
  base_slug := lower(translate(
    NEW.name,
    'àâäáãåèêëéìîïíòôöóõùûüúñçÀÂÄÁÃÅÈÊËÉÌÎÏÍÒÔÖÓÕÙÛÜÚÑÇ',
    'aaaaaaeeeeiiiiooooouuuuncAAAAAAEEEEIIIIOOOOOUUUUNC'
  ));
  base_slug := regexp_replace(base_slug, '[^a-z0-9]+', '-', 'g');
  base_slug := trim(both '-' from base_slug);
  IF base_slug = '' THEN base_slug := 'carte'; END IF;

  candidate := base_slug;
  LOOP
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.maps m
      WHERE m.universe_id = NEW.universe_id AND m.map_key = candidate
    );
    attempt := attempt + 1;
    candidate := base_slug || '-' || attempt;
    IF attempt > 200 THEN
      RAISE EXCEPTION 'Could not generate unique map_key';
    END IF;
  END LOOP;

  NEW.map_key := candidate;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS set_map_key ON public.maps;
CREATE TRIGGER set_map_key
  BEFORE INSERT ON public.maps
  FOR EACH ROW EXECUTE FUNCTION public.set_map_key();

-- Le map_key ne doit plus jamais changer après création : des
-- lignes map_markers/map_layers peuvent déjà le référencer.
CREATE OR REPLACE FUNCTION public.lock_map_key()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.map_key := OLD.map_key;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS lock_map_key ON public.maps;
CREATE TRIGGER lock_map_key
  BEFORE UPDATE ON public.maps
  FOR EACH ROW EXECUTE FUNCTION public.lock_map_key();

-- ── 3. RLS ────────────────────────────────────────────────────
ALTER TABLE public.maps ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "maps_select" ON public.maps;
CREATE POLICY "maps_select" ON public.maps FOR SELECT
  USING (public.is_universe_member(universe_id));

DROP POLICY IF EXISTS "maps_insert_owner" ON public.maps;
CREATE POLICY "maps_insert_owner" ON public.maps FOR INSERT
  WITH CHECK (
    created_by = auth.uid()
    AND public.has_universe_role(universe_id, ARRAY['owner'])
  );

DROP POLICY IF EXISTS "maps_update_owner" ON public.maps;
CREATE POLICY "maps_update_owner" ON public.maps FOR UPDATE
  USING (public.has_universe_role(universe_id, ARRAY['owner']))
  WITH CHECK (public.has_universe_role(universe_id, ARRAY['owner']));

DROP POLICY IF EXISTS "maps_delete_owner" ON public.maps;
CREATE POLICY "maps_delete_owner" ON public.maps FOR DELETE
  USING (public.has_universe_role(universe_id, ARRAY['owner']));

-- ── 4. Bucket Storage pour les images de carte ─────────────────
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('map-images', 'map-images', true, 15728640, ARRAY['image/jpeg'])
ON CONFLICT (id) DO NOTHING;

-- Vérifie que le 1er segment du chemin de stockage (universe_id)
-- est bien géré par un owner. Échoue proprement (FALSE) au lieu
-- de lever une erreur SQL si le segment n'est pas un UUID valide.
CREATE OR REPLACE FUNCTION public.storage_path_universe_role(p_name TEXT, p_roles TEXT[])
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_universe_id UUID;
BEGIN
  BEGIN
    v_universe_id := ((storage.foldername(p_name))[1])::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN FALSE;
  END;
  RETURN public.has_universe_role(v_universe_id, p_roles);
END;
$$;

GRANT EXECUTE ON FUNCTION public.storage_path_universe_role(TEXT, TEXT[]) TO authenticated;

DROP POLICY IF EXISTS "map_images_public_read" ON storage.objects;
CREATE POLICY "map_images_public_read"
  ON storage.objects FOR SELECT
  TO public
  USING (bucket_id = 'map-images');

DROP POLICY IF EXISTS "map_images_insert_owner" ON storage.objects;
CREATE POLICY "map_images_insert_owner"
  ON storage.objects FOR INSERT
  TO authenticated
  WITH CHECK (
    bucket_id = 'map-images'
    AND public.storage_path_universe_role(name, ARRAY['owner'])
  );

DROP POLICY IF EXISTS "map_images_update_owner" ON storage.objects;
CREATE POLICY "map_images_update_owner"
  ON storage.objects FOR UPDATE
  TO authenticated
  USING (
    bucket_id = 'map-images'
    AND public.storage_path_universe_role(name, ARRAY['owner'])
  );

DROP POLICY IF EXISTS "map_images_delete_owner" ON storage.objects;
CREATE POLICY "map_images_delete_owner"
  ON storage.objects FOR DELETE
  TO authenticated
  USING (
    bucket_id = 'map-images'
    AND public.storage_path_universe_role(name, ARRAY['owner'])
  );

-- ══════════════════════════════════════════════════════════════
-- Chemin de stockage : map-images/{universe_id}/{map_id|tmp_xxx}.jpg
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/23_maps_config.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/24_leave_universe_transfer_ownership.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Départ d'un univers : transfert de propriété au owner
-- À exécuter dans Supabase Dashboard > SQL Editor > New query
-- (nécessite sql/18_universes_phase1.sql et sql/19_campaign_sharing.sql)
-- ══════════════════════════════════════════════════════════════
--
-- Quand un membre quitte un univers (de son plein gré, ou après avoir
-- été retiré par un owner/admin), tout ce qu'il y a créé (personnages,
-- chroniques, documents, couche de carte + marqueurs) est transféré
-- au propriétaire de l'univers au lieu de rester bloqué derrière un
-- compte qui n'y a plus accès. Les tags personnels liés sont nettoyés
-- comme lors d'un transfert d'objet classique (cf. transfer_item /
-- _cleanup_char_tags_on_transfer / _cleanup_doc_tags_on_transfer).
--
-- Remplace la suppression directe de universe_members côté client :
-- le frontend doit désormais appeler ce RPC plutôt que
-- `sb.from('universe_members').delete()...`.
-- ══════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.remove_universe_member(
  p_universe_id UUID,
  p_user_id     UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_owner_id        UUID;
  v_char_id         UUID;
  v_doc_id          UUID;
  v_map_key         TEXT;
  v_owner_has_layer BOOLEAN;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT owner_id INTO v_owner_id
  FROM public.universes
  WHERE id = p_universe_id;

  IF v_owner_id IS NULL THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  IF p_user_id = v_owner_id THEN
    RAISE EXCEPTION 'Le propriétaire ne peut pas quitter son propre univers';
  END IF;

  IF auth.uid() <> p_user_id AND NOT public.has_universe_role(p_universe_id, ARRAY['owner','admin']) THEN
    RAISE EXCEPTION 'Non autorisé';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.universe_members
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  ) THEN
    RAISE EXCEPTION 'Cet utilisateur n''est pas membre de cet univers';
  END IF;

  -- ── Personnages ────────────────────────────────────────────
  FOR v_char_id IN
    SELECT id FROM public.characters
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  LOOP
    PERFORM public._cleanup_char_tags_on_transfer(v_char_id, p_user_id);
    UPDATE public.characters SET user_id = v_owner_id, updated_at = NOW() WHERE id = v_char_id;
  END LOOP;

  -- ── Chroniques (pas de système de tags) ───────────────────
  UPDATE public.chronicles
  SET user_id = v_owner_id, updated_at = NOW()
  WHERE universe_id = p_universe_id AND user_id = p_user_id;

  -- ── Documents ──────────────────────────────────────────────
  FOR v_doc_id IN
    SELECT id FROM public.documents
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  LOOP
    PERFORM public._cleanup_doc_tags_on_transfer(v_doc_id, p_user_id);
    UPDATE public.documents SET user_id = v_owner_id, updated_at = NOW() WHERE id = v_doc_id;
  END LOOP;

  -- ── Couches de carte + marqueurs ──────────────────────────
  -- map_layers a une contrainte UNIQUE(user_id, map_key) : si le
  -- propriétaire possède déjà une couche pour cette carte, on fusionne
  -- les marqueurs dans la sienne et on supprime la couche devenue vide
  -- plutôt que de réassigner (ce qui violerait la contrainte).
  FOR v_map_key IN
    SELECT DISTINCT map_key FROM public.map_layers
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  LOOP
    UPDATE public.map_markers
    SET user_id = v_owner_id, updated_at = NOW()
    WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;

    SELECT EXISTS (
      SELECT 1 FROM public.map_layers
      WHERE universe_id = p_universe_id AND user_id = v_owner_id AND map_key = v_map_key
    ) INTO v_owner_has_layer;

    IF v_owner_has_layer THEN
      DELETE FROM public.map_layers
      WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;
    ELSE
      UPDATE public.map_layers
      SET user_id = v_owner_id, updated_at = NOW()
      WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;
    END IF;
  END LOOP;

  -- ── Tags personnels devenus orphelins (aucun objet ne les utilise) ──
  DELETE FROM public.tags
  WHERE universe_id = p_universe_id AND user_id = p_user_id
    AND NOT EXISTS (
      SELECT 1 FROM public.character_tags ct
      JOIN public.characters c ON c.id = ct.character_id
      WHERE ct.tag_id = tags.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.followed_character_tags fct
      WHERE fct.tag_id = tags.id AND fct.user_id = p_user_id
    );

  DELETE FROM public.doc_tags
  WHERE universe_id = p_universe_id AND user_id = p_user_id
    AND NOT EXISTS (
      SELECT 1 FROM public.document_tags dt
      JOIN public.documents d ON d.id = dt.document_id
      WHERE dt.tag_id = doc_tags.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.followed_document_tags fdt
      WHERE fdt.tag_id = doc_tags.id AND fdt.user_id = p_user_id
    );

  -- ── Retrait de l'univers ───────────────────────────────────
  DELETE FROM public.universe_members
  WHERE universe_id = p_universe_id AND user_id = p_user_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.remove_universe_member(UUID, UUID) TO authenticated;

-- ══════════════════════════════════════════════════════════════
-- Résumé :
--  • À appeler via sb.rpc('remove_universe_member', { p_universe_id, p_user_id })
--    aussi bien pour un départ volontaire (p_user_id = soi-même) que pour
--    un retrait par un owner/admin (p_user_id = la cible).
--  • Personnages / chroniques / documents / couches de carte + marqueurs
--    créés par le membre partant deviennent la propriété du owner.
--  • Les campagnes ne sont pas concernées : elles n'appartiennent déjà
--    qu'au owner (cf. sql/19_campaign_sharing.sql).
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/24_leave_universe_transfer_ownership.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/25_unify_tags.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Unification du système de tags
-- À exécuter sur une base ayant déjà reçu sql/00_fresh_install.sql
-- (jusqu'à sql/24_leave_universe_transfer_ownership.sql inclus).
--
-- Les tags redeviennent une organisation strictement personnelle :
-- un utilisateur pose ses tags sur n'importe quel personnage ou
-- document qu'il peut voir (les siens ou ceux d'un autre membre de
-- l'univers), indépendamment de qui possède l'objet. Il n'y a donc
-- plus lieu de distinguer "mes tags sur mes objets" (character_tags)
-- de "mes tags sur les objets des autres" (followed_character_tags) :
-- les deux sont fusionnés en une seule table par domaine.
--
-- Conséquence : plus aucun mécanisme ne copie les tags du créateur
-- d'un objet vers l'utilisateur qui le consulte (sync_owner_tags et
-- ses helpers sont supprimés — ils étaient de toute façon déjà
-- inertes côté frontend, et cassés depuis la suppression de
-- followed_characters/followed_documents dans sql/19_campaign_sharing.sql).
-- Un transfert de propriété (transfer_item, remove_universe_member)
-- ne touche donc plus aux tags : ce sont ceux de qui les a posés,
-- pas de qui possède l'objet.
--
-- Migration destructive : aucune donnée existante à préserver.
-- ══════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Personnages : character_tags + followed_character_tags → character_tags ──

DROP TABLE IF EXISTS public.character_tags CASCADE;
ALTER TABLE public.followed_character_tags RENAME TO character_tags;
ALTER TABLE public.character_tags DROP COLUMN IF EXISTS id;

ALTER TABLE public.character_tags DROP CONSTRAINT IF EXISTS followed_character_tags_pkey;
ALTER TABLE public.character_tags
  ADD CONSTRAINT character_tags_pkey PRIMARY KEY (universe_id, user_id, character_id, tag_id);

DROP INDEX IF EXISTS public.idx_followed_character_tags_user;
DROP INDEX IF EXISTS public.idx_followed_character_tags_character;
DROP INDEX IF EXISTS public.followed_character_tags_universe_user_idx;
CREATE INDEX IF NOT EXISTS character_tags_universe_user_idx ON public.character_tags(universe_id, user_id);
CREATE INDEX IF NOT EXISTS character_tags_character_idx     ON public.character_tags(character_id);

ALTER TABLE public.character_tags ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "character_tags_select" ON public.character_tags;
DROP POLICY IF EXISTS "character_tags_insert" ON public.character_tags;
DROP POLICY IF EXISTS "character_tags_delete" ON public.character_tags;
DROP POLICY IF EXISTS "Users manage their own followed tags" ON public.character_tags;
CREATE POLICY "character_tags_manage_own" ON public.character_tags
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

-- ── 2. Documents : document_tags + followed_document_tags → document_tags ──

DROP TABLE IF EXISTS public.document_tags CASCADE;
ALTER TABLE public.followed_document_tags RENAME TO document_tags;

ALTER TABLE public.document_tags DROP CONSTRAINT IF EXISTS followed_document_tags_pkey;
ALTER TABLE public.document_tags
  ADD CONSTRAINT document_tags_pkey PRIMARY KEY (universe_id, user_id, document_id, tag_id);

DROP INDEX IF EXISTS public.followed_document_tags_universe_user_idx;
CREATE INDEX IF NOT EXISTS document_tags_universe_user_idx ON public.document_tags(universe_id, user_id);
CREATE INDEX IF NOT EXISTS document_tags_document_idx      ON public.document_tags(document_id);

ALTER TABLE public.document_tags ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users manage own document tags" ON public.document_tags;
DROP POLICY IF EXISTS "Users manage own followed doc tags" ON public.document_tags;
CREATE POLICY "document_tags_manage_own" ON public.document_tags
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

-- ── 3. Fonctions obsolètes de partage/sync ────────────────────

DROP FUNCTION IF EXISTS public._cleanup_char_tags_on_transfer(UUID, UUID);
DROP FUNCTION IF EXISTS public._cleanup_doc_tags_on_transfer(UUID, UUID);
DROP FUNCTION IF EXISTS public.sync_owner_tags(TEXT, TEXT);
DROP FUNCTION IF EXISTS public.sync_char_tags_to_follower(UUID, UUID);
DROP FUNCTION IF EXISTS public.sync_doc_tags_to_follower(UUID, UUID);

-- ── 4. cleanup_orphan_char_tags / cleanup_orphan_doc_tags — adaptées ──

CREATE OR REPLACE FUNCTION public.cleanup_orphan_char_tags(
  p_user_id UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_tag_id UUID;
BEGIN
  FOR v_tag_id IN
    SELECT t.id
    FROM   public.tags t
    WHERE  t.user_id = p_user_id
      AND  NOT EXISTS (
             SELECT 1 FROM public.character_tags ct
             WHERE ct.tag_id = t.id AND ct.user_id = p_user_id
           )
  LOOP
    DELETE FROM public.tags WHERE id = v_tag_id AND user_id = p_user_id;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.cleanup_orphan_char_tags(UUID) TO authenticated;

CREATE OR REPLACE FUNCTION public.cleanup_orphan_doc_tags(
  p_user_id UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_tag_id UUID;
BEGIN
  FOR v_tag_id IN
    SELECT t.id
    FROM   public.doc_tags t
    WHERE  t.user_id = p_user_id
      AND  NOT EXISTS (
             SELECT 1 FROM public.document_tags dt
             WHERE dt.tag_id = t.id AND dt.user_id = p_user_id
           )
  LOOP
    DELETE FROM public.doc_tags WHERE id = v_tag_id AND user_id = p_user_id;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.cleanup_orphan_doc_tags(UUID) TO authenticated;

-- ── 5. transfer_item — ne nettoie plus les tags (ils restent à qui les a posés) ──

CREATE OR REPLACE FUNCTION public.transfer_item(
  p_item_type   TEXT,
  p_item_id     UUID,
  p_to_username TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_caller_id    UUID := auth.uid();
  v_target_id    UUID;
  v_item_user_id UUID;
  v_map_key      TEXT;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated');
  END IF;

  SELECT id INTO v_target_id
  FROM public.profiles
  WHERE lower(username) = lower(trim(p_to_username))
  LIMIT 1;

  IF v_target_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'user_not_found');
  END IF;

  IF v_target_id = v_caller_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'same_user');
  END IF;

  IF p_item_type = 'char' THEN
    SELECT user_id INTO v_item_user_id FROM public.characters WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    UPDATE public.characters SET user_id = v_target_id, updated_at = NOW() WHERE id = p_item_id;

  ELSIF p_item_type = 'chr' THEN
    SELECT user_id INTO v_item_user_id FROM public.chronicles WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    UPDATE public.chronicles SET user_id = v_target_id, updated_at = NOW() WHERE id = p_item_id;

  ELSIF p_item_type = 'doc' THEN
    SELECT user_id INTO v_item_user_id FROM public.documents WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    UPDATE public.documents SET user_id = v_target_id, updated_at = NOW() WHERE id = p_item_id;

  ELSIF p_item_type = 'map' THEN
    SELECT user_id, map_key INTO v_item_user_id, v_map_key FROM public.map_layers WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    -- Transfère uniquement les marqueurs de la carte concernée (comme avant).
    UPDATE public.map_markers
      SET user_id = v_target_id, updated_at = NOW()
      WHERE user_id = v_caller_id AND map_key = v_map_key;
    UPDATE public.map_layers
      SET user_id = v_target_id, updated_at = NOW()
      WHERE id = p_item_id;

  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_type');
  END IF;

  RETURN jsonb_build_object('ok', true, 'item_id', p_item_id, 'to_user_id', v_target_id);
END;
$$;

GRANT EXECUTE ON FUNCTION public.transfer_item(TEXT, UUID, TEXT) TO authenticated;

-- ── 6. remove_universe_member — idem, plus nettoyage tags du partant ──

CREATE OR REPLACE FUNCTION public.remove_universe_member(
  p_universe_id UUID,
  p_user_id     UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_owner_id        UUID;
  v_map_key         TEXT;
  v_owner_has_layer BOOLEAN;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT owner_id INTO v_owner_id
  FROM public.universes
  WHERE id = p_universe_id;

  IF v_owner_id IS NULL THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  IF p_user_id = v_owner_id THEN
    RAISE EXCEPTION 'Le propriétaire ne peut pas quitter son propre univers';
  END IF;

  IF auth.uid() <> p_user_id AND NOT public.has_universe_role(p_universe_id, ARRAY['owner','admin']) THEN
    RAISE EXCEPTION 'Non autorisé';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.universe_members
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  ) THEN
    RAISE EXCEPTION 'Cet utilisateur n''est pas membre de cet univers';
  END IF;

  -- ── Personnages / chroniques / documents : transfert direct au owner ──
  UPDATE public.characters SET user_id = v_owner_id, updated_at = NOW()
    WHERE universe_id = p_universe_id AND user_id = p_user_id;
  UPDATE public.chronicles SET user_id = v_owner_id, updated_at = NOW()
    WHERE universe_id = p_universe_id AND user_id = p_user_id;
  UPDATE public.documents SET user_id = v_owner_id, updated_at = NOW()
    WHERE universe_id = p_universe_id AND user_id = p_user_id;

  -- ── Couches de carte + marqueurs ──────────────────────────
  -- map_layers a une contrainte UNIQUE(universe_id, user_id, map_key) : si le
  -- propriétaire possède déjà une couche pour cette carte, on fusionne
  -- les marqueurs dans la sienne et on supprime la couche devenue vide
  -- plutôt que de réassigner (ce qui violerait la contrainte).
  FOR v_map_key IN
    SELECT DISTINCT map_key FROM public.map_layers
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  LOOP
    UPDATE public.map_markers
    SET user_id = v_owner_id, updated_at = NOW()
    WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;

    SELECT EXISTS (
      SELECT 1 FROM public.map_layers
      WHERE universe_id = p_universe_id AND user_id = v_owner_id AND map_key = v_map_key
    ) INTO v_owner_has_layer;

    IF v_owner_has_layer THEN
      DELETE FROM public.map_layers
      WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;
    ELSE
      UPDATE public.map_layers
      SET user_id = v_owner_id, updated_at = NOW()
      WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;
    END IF;
  END LOOP;

  -- ── Tags personnels du partant, pour cet univers ──────────────
  -- Ce sont ses tags à lui (indépendants des objets qu'il possédait) :
  -- ils n'ont plus de raison d'exister une fois qu'il a quitté l'univers.
  -- Cascade automatiquement sur character_tags / document_tags.
  DELETE FROM public.tags     WHERE universe_id = p_universe_id AND user_id = p_user_id;
  DELETE FROM public.doc_tags WHERE universe_id = p_universe_id AND user_id = p_user_id;

  -- ── Retrait de l'univers ───────────────────────────────────
  DELETE FROM public.universe_members
  WHERE universe_id = p_universe_id AND user_id = p_user_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.remove_universe_member(UUID, UUID) TO authenticated;

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Résumé :
--  • character_tags(user_id, character_id, tag_id, universe_id) et
--    document_tags(user_id, document_id, tag_id, universe_id) sont
--    désormais les seules tables de liaison, quel que soit le
--    propriétaire de l'objet tagué.
--  • Le frontend doit appeler ces deux tables directement (avec
--    eq('user_id', currentUser.id)) au lieu de distinguer
--    character_tags / followed_character_tags.
--  • sync_owner_tags, sync_char_tags_to_follower, sync_doc_tags_to_follower,
--    _cleanup_char_tags_on_transfer, _cleanup_doc_tags_on_transfer
--    n'existent plus.
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/25_unify_tags.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/26_map_layer_remove_title_description.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Suppression du titre et de la description des couches
-- À exécuter sur une base ayant déjà reçu sql/00_fresh_install.sql
-- (jusqu'à sql/25_unify_tags.sql inclus).
--
-- Une couche de carte (map_layers) n'a pas besoin de nom ni de
-- description : elle est entièrement définie par la carte à laquelle
-- elle est liée (map_key) et son propriétaire (user_id). Le frontend
-- identifie désormais une couche par le nom de la carte associée et
-- le nom d'utilisateur du propriétaire, jamais par un champ libre.
--
-- Migration destructive : les titres/descriptions existants sont perdus.
-- ══════════════════════════════════════════════════════════════

BEGIN;

ALTER TABLE public.map_layers DROP COLUMN IF EXISTS title;
ALTER TABLE public.map_layers DROP COLUMN IF EXISTS description;

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Résumé :
--  • map_layers n'a plus de colonnes title/description.
--  • Toute requête sb.from('map_layers').select(...) doit être mise à
--    jour pour retirer ces champs (cf. map.js, campaigns.js, export.js).
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/26_map_layer_remove_title_description.sql
